from collections import defaultdict

bars_by_color = defaultdict(list)
for r in range(15):
    for c in range(10):
        color = grid[r][c]
        if color != 0:
            start = None
            for k in range(c, 10):
                if grid[r][k] == color:
                    if start is None:
                        start = k
                    else:
                        continue # same color
                else:
                    if start is not None:
                        bars_by_color[color].append((start, c-1 if start != 10 else 10)) # incomplete
                    break

# Better approach: find connected horizontal segments
horizontal_segments = []
for r in range(15):
    i = 0
    while i < 10:
        if grid[r][i] != 0:
            start = i
            color = grid[r][i]
            j = i
            while j < 10 and grid[r][j] == color:
                j += 1
            horizontal_segments.append({'color': color, 'row': r, 'col': start, 'width': j-start})
            i = j
        else:
            i += 1

print("Horizontal segments:")
for seg in horizontal_segments:
    print(seg)

